// graphql.config.mjs
// The API reference pages are generated by the nuxt-theme from generate-docs.ts;
// this project only renders the Markdown copies (`pnpm run copies`).
import { referenceOptions } from "./lib/reference-options.mjs";

// Formatter paths must be absolute: a relative path is not resolved from the project folder
const local = (path) => new URL(path, import.meta.url).href;

export default {
  projects: {
    markdown: {
      schema: referenceOptions.schema,
      extensions: {
        "graphql-markdown": {
          // Same content settings as the pages
          loaders: referenceOptions.loaders,
          printTypeOptions: referenceOptions.printTypeOptions,
          decorators: referenceOptions.decorators,
          // A folder used only for the copies
          rootPath: "./.markdown-copies",
          // The theme's default, so a copy has the path of its page
          baseURL: "api-reference",
          formatter: local("./lib/markdown-copy.mjs"),
          // The homepage is a page of the site, not a schema entity
          homepage: false,
          // No `{#id}` heading IDs, which plain Markdown doesn't support
          docOptions: { sectionHeaderId: false },
          telemetry: false,
        },
      },
    },
  },
};
